insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g7_ss_v1'
from (values
('113.19.c.1.A',3,'Which era in Texas history came right after the Texas Revolution?','["the Republic of Texas", "the oil boom", "the Great Depression", "the Civil War era"]'::jsonb,0,'Texas was an independent republic from 1836 to 1845.','original'),
('113.19.c.1.A',3,'Which era includes the long ranch and trail-drive period after the Civil War?','["the Space Age", "the Cattle Kingdom era", "the Spanish colonial era", "the New Deal"]'::jsonb,1,'Cattle drives dominated Texas in the late 1800s.','original'),
('113.19.c.1.B',3,'What happened in Texas in 1836?','["oil was found at Spindletop", "Texas joined the Union", "Texas declared independence and won at San Jacinto", "Texas seceded from the Union"]'::jsonb,2,'Independence came in 1836.','original'),
('113.19.c.1.B',3,'What happened in 1845?','["the Alamo fell", "Texas left the Union", "Texas declared independence", "Texas was annexed by the United States"]'::jsonb,3,'Texas became the 28th state.','original'),
('113.19.c.1.B',3,'In what year did oil gush from Spindletop?','["1901", "1929", "1845", "1836"]'::jsonb,0,'Spindletop began the Texas oil boom.','original'),
('113.19.c.2.A',3,'Which group lived on the Plains and followed bison herds before European colonization?','["Coahuiltecan", "Comanche", "Karankawa", "Caddo farmers"]'::jsonb,1,'Plains peoples were nomadic hunters.','original'),
('113.19.c.2.A',3,'Which American Indian groups of East Texas built mounds and farmed corn?','["Apache", "Comanche", "Caddo", "Karankawa"]'::jsonb,2,'Caddo were farmers.','original'),
('113.19.c.2.A',4,'Which group along the Gulf Coast lived by fishing and gathering?','["Caddo", "Comanche", "Pueblo", "Karankawa"]'::jsonb,3,'Coastal people used the sea.','original'),
('113.19.c.2.B',3,'Which Spanish explorer was shipwrecked on the Texas coast and traveled across the region in the 1530s?','["Cabeza de Vaca", "Sam Houston", "Moses Austin", "Stephen F. Austin"]'::jsonb,0,'He wrote about the peoples of Texas.','original'),
('113.19.c.2.B',4,'Which French explorer''s failed colony near Matagorda Bay led Spain to settle East Texas?','["Pineda", "La Salle", "Coronado", "Cortez"]'::jsonb,1,'French presence alarmed Spain.','original'),
('113.19.c.2.C',3,'What was the main goal of Spanish missions in Texas?','["to mine gold", "to train armies", "to convert American Indians to Christianity and claim land", "to build railroads"]'::jsonb,2,'Missions spread religion and Spanish control.','original'),
('113.19.c.2.C',3,'San Antonio de Bexar was founded in 1718 as a Spanish...','["railroad stop", "cattle market", "oil field", "presidio and mission settlement"]'::jsonb,3,'It became the heart of Spanish Texas.','original'),
('113.19.c.2.D',3,'In 1821, Mexico became an independent nation after winning independence from...','["Spain", "the United States", "England", "France"]'::jsonb,0,'The Mexican War of Independence ended Spanish rule.','original'),
('113.19.c.2.D',4,'The Mexican Constitution of 1824 created the state of...','["Tejas Libre", "Coahuila y Tejas", "Lone Star State", "Nueces Republic"]'::jsonb,1,'Texas was joined with Coahuila.','original'),
('113.19.c.2.E',3,'Who received the first permission to bring American settlers to Texas, though he died before doing so?','["Davy Crockett", "Sam Houston", "Moses Austin", "Santa Anna"]'::jsonb,2,'His son carried on the colony.','original'),
('113.19.c.2.E',3,'Who is called the ''Father of Texas'' for founding the first Anglo colony?','["Anson Jones", "William Travis", "Mirabeau Lamar", "Stephen F. Austin"]'::jsonb,3,'He led the Old Three Hundred.','original'),
('113.19.c.2.E',3,'Which tejano leader supported the Texas cause and served as a leader in the Revolution?','["Jose Antonio Navarro", "Zachary Taylor", "Jefferson Davis", "Santa Anna"]'::jsonb,0,'Navarro signed the Declaration of Independence.','original'),
('113.19.c.2.F',4,'Which best contrasts Spanish and Anglo settlement purposes in Texas?','["neither wanted land", "Spain wanted to protect borders and spread religion; Anglos mainly wanted land for farming and cotton", "both wanted to build railroads", "both wanted gold only"]'::jsonb,1,'Different motives shaped settlement.','original'),
('113.19.c.3.A',3,'Which law in 1830 banned further immigration from the United States into Texas?','["Treaty of Velasco", "Homestead Act", "Law of April 6, 1830", "Declaration of Independence"]'::jsonb,2,'It angered Anglo settlers.','original'),
('113.19.c.3.A',4,'The Fredonian Rebellion of 1826 was an early dispute between settlers and...','["the Comanche", "the Spanish crown", "the United States Army", "the Mexican government"]'::jsonb,3,'It was an early sign of tension.','original'),
('113.19.c.3.B',3,'Who commanded the Texan army and won the Battle of San Jacinto?','["Sam Houston", "William Travis", "Santa Anna", "Stephen F. Austin"]'::jsonb,0,'Houston led the final victory.','original'),
('113.19.c.3.B',3,'Who was the Mexican president and general who led the invasion of Texas in 1836?','["James Fannin", "Antonio Lopez de Santa Anna", "Sam Houston", "Mirabeau Lamar"]'::jsonb,1,'Santa Anna led the Mexican army.','original'),
('113.19.c.3.B',4,'Who commanded the Texan defenders at the Alamo along with James Bowie?','["Sam Houston", "Anson Jones", "William B. Travis", "Stephen F. Austin"]'::jsonb,2,'Travis wrote the famous letter asking for help.','original'),
('113.19.c.3.C',3,'The Battle of Gonzales in 1835 began when Texans refused to hand over a...','["treaty", "horse", "flag", "cannon"]'::jsonb,3,'''Come and Take It'' became the rallying cry.','original'),
('113.19.c.3.C',4,'What happened at Goliad in March 1836?','["Texan prisoners under Fannin were executed", "Texas was annexed", "Texans won a decisive victory", "Santa Anna surrendered"]'::jsonb,0,'The Goliad massacre fueled outrage.','original'),
('113.19.c.3.C',3,'The Battle of San Jacinto lasted about...','["three days", "eighteen minutes", "two months", "one week"]'::jsonb,1,'It was a quick and decisive Texan victory.','original'),
('113.19.c.4.A',3,'Who was the first president of the Republic of Texas?','["Stephen F. Austin", "Anson Jones", "Sam Houston", "Mirabeau B. Lamar"]'::jsonb,2,'Houston served two nonconsecutive terms.','original'),
('113.19.c.4.A',4,'President Lamar is known as the ''Father of Texas Education'' because he promoted...','["railroad subsidies", "a national bank", "oil drilling", "public land set aside for schools and universities"]'::jsonb,3,'Lamar championed education.','original'),
('113.19.c.4.B',3,'Why did many Texans support annexation to the United States?','["security from Mexico and relief from public debt", "to become a British colony", "to end all trade", "to leave North America"]'::jsonb,0,'Texas faced debt and threats.','original'),
('113.19.c.4.C',3,'The U.S.-Mexican War ended with the Treaty of...','["Versailles", "Guadalupe Hidalgo", "Paris", "Velasco"]'::jsonb,1,'Mexico recognized the Rio Grande boundary.','original'),
('113.19.c.4.C',4,'The Compromise of 1850 settled Texas''s boundary dispute with...','["Canada", "Louisiana", "the New Mexico Territory", "Oklahoma"]'::jsonb,2,'Texas gave up claims for federal debt relief.','original'),
('113.19.c.5.A',3,'What was a central reason for Texas''s role in the Civil War?','["railroad subsidies", "the invention of the cotton gin", "oil disputes", "the expansion and defense of slavery"]'::jsonb,3,'Slavery was central to secession.','original'),
('113.19.c.5.B',3,'Which battle in 1863 led Confederate troops to prevent a Union invasion at Sabine Pass?','["Battle of Sabine Pass", "Battle of Gettysburg", "Battle of San Jacinto", "Battle of the Alamo"]'::jsonb,0,'A small force turned back a larger fleet.','original'),
('113.19.c.5.B',4,'The last land battle of the Civil War took place in Texas at...','["Goliad", "Palmito Ranch", "Gettysburg", "Gonzales"]'::jsonb,1,'It occurred after Lee''s surrender.','original'),
('113.19.c.5.C',3,'What happened in Texas on June 19, 1865, now celebrated as Juneteenth?','["the Alamo fell", "Texas joined the Union", "enslaved people were told they were free", "oil was discovered"]'::jsonb,2,'General Granger announced emancipation in Galveston.','original'),
('113.19.c.5.C',4,'During Reconstruction in Texas, the Freedmen''s Bureau helped formerly enslaved people with...','["oil drilling", "cattle drives", "railroad construction", "education, work contracts and legal aid"]'::jsonb,3,'The Bureau supported freedpeople.','original'),
('113.19.c.6.A',3,'Which law encouraged settlers to move onto Western lands by granting 160 acres?','["the Homestead Act", "the Missouri Compromise", "the Dawes Act", "the Compromise of 1850"]'::jsonb,0,'It offered free land to farmers.','original'),
('113.19.c.6.A',3,'Which famous Comanche leader fought to protect Texas Plains homelands?','["Sam Houston", "Quanah Parker", "Jose Navarro", "Stephen F. Austin"]'::jsonb,1,'Quanah Parker later worked for peace.','original'),
('113.19.c.6.B',3,'Cattle drives moved herds north along which famous route from Texas to Kansas railheads?','["the Santa Fe Trail", "the Camino Real", "the Chisholm Trail", "the Oregon Trail"]'::jsonb,2,'Longhorn herds reached rail towns.','original'),
('113.19.c.6.B',3,'The invention of barbed wire led to the end of the open range because it allowed ranchers to...','["drive cattle faster", "plant cotton", "ship oil", "fence their land"]'::jsonb,3,'Fencing closed the open range.','original'),
('113.19.c.6.C',3,'How did railroads change Texas in the late 1800s?','["they connected towns and moved crops and cattle to markets", "they blocked trade", "they ended farming", "they removed cities"]'::jsonb,0,'Railroads boosted growth.','original'),
('113.19.c.6.D',4,'Sharecropping and tenant farming became common after the Civil War because...','["cotton was banned", "many farmers lacked money to buy land", "land was free for all", "railroads were closed"]'::jsonb,1,'Many farmers fell into debt.','original'),
('113.19.c.7.A',3,'How did the oil industry lead to the industrialization of Texas?','["it banned railroads", "it ended all manufacturing", "it created refineries, jobs and new towns", "it removed cities"]'::jsonb,2,'Oil attracted industry.','original'),
('113.19.c.7.B',4,'A ''boom-and-bust'' cycle in the oil industry means...','["steady prices forever", "no demand", "permanent growth", "prosperity followed by downturns as prices change"]'::jsonb,3,'Prices and production rise and fall.','original'),
('113.19.c.7.C',3,'The Populist movement in Texas sought help mainly for...','["farmers facing high costs and debt", "railroad owners", "oil companies", "cattle barons"]'::jsonb,0,'Populists pushed for farm reforms.','original'),
('113.19.c.7.D',3,'The League of United Latin American Citizens (LULAC), founded in Texas in 1929, worked for...','["railroad safety", "civil rights for Mexican Americans", "ranching rights", "oil leases"]'::jsonb,1,'LULAC fought discrimination.','original'),
('113.19.c.7.D',4,'Which Texas case led the Supreme Court to end the Democratic white primary in 1944?','["Plessy v. Ferguson", "Brown v. Board of Education", "Smith v. Allwright", "Marbury v. Madison"]'::jsonb,2,'Texas voting rights were advanced.','original'),
('113.19.c.7.E',3,'During World War II, many Texans worked in...','["mining gold", "cattle drives only", "Spanish missions", "defense industries such as shipbuilding and aircraft"]'::jsonb,3,'The war boosted industry.','original'),
('113.19.c.7.E',3,'The Great Depression hit Texas farmers hard because...','["crop prices fell and the Dust Bowl damaged farmland", "railroads closed", "oil was cheap", "cattle drives resumed"]'::jsonb,0,'Economic collapse hurt farms.','original'),
('113.19.c.8.A',3,'Which Texas region contains the Guadalupe Mountains and Big Bend?','["Great Plains", "Mountains and Basins", "Coastal Plains", "North Central Plains"]'::jsonb,1,'It is in West Texas.','original'),
('113.19.c.8.A',3,'Which region includes the Panhandle and the Llano Estacado?','["Mountains and Basins", "Coastal Plains", "Great Plains", "Piney Woods"]'::jsonb,2,'It is a high, flat region.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
