from (values
('113.19.c.8.A',3,'Which region borders the Gulf of Mexico and includes Houston?','["Great Plains", "Mountains and Basins", "North Central Plains", "Coastal Plains"]'::jsonb,3,'It is low, flat and humid.','original'),
('113.19.c.8.B',3,'Which Texas city is a major seaport on the Gulf Coast?','["Houston", "Abilene", "Amarillo", "Lubbock"]'::jsonb,0,'Houston has a large port.','original'),
('113.19.c.8.C',4,'How do irrigation and the Ogallala Aquifer affect the High Plains economy?','["they stop farming", "they allow farming in a dry region but water supplies are limited", "they end ranching", "they create oceans"]'::jsonb,1,'Irrigation supports crops.','original'),
('113.19.c.9.A',3,'Building dams and reservoirs in Texas is an example of how Texans have...','["avoided the environment", "created climate", "modified the environment", "ended droughts permanently"]'::jsonb,2,'Dams store water.','original'),
('113.19.c.9.B',3,'The 1900 Galveston Hurricane showed that...','["Galveston is inland", "storms never matter", "hurricanes cannot hit Texas", "natural disasters can reshape settlement and the economy"]'::jsonb,3,'Galveston''s recovery led to a seawall and Houston''s growth.','original'),
('113.19.c.9.B',3,'The Dust Bowl damaged Texas farmland mainly because of...','["drought and poor farming practices", "volcano eruptions", "too many forests", "too much rain"]'::jsonb,0,'Soil blew away.','original'),
('113.19.c.10.A',3,'German and Czech immigrants who came to Texas in the 1800s mainly settled in...','["the Panhandle", "Central Texas", "East Texas swamps", "West Texas deserts"]'::jsonb,1,'They built farming communities.','original'),
('113.19.c.10.A',4,'Many Mexican immigrants came to Texas in the early 1900s to escape...','["the Great Depression", "the Civil War", "the Mexican Revolution", "World War II"]'::jsonb,2,'Violence in Mexico pushed migration.','original'),
('113.19.c.10.B',3,'How has immigration influenced Texas culture?','["by eliminating cities", "by ending traditions", "by banning languages", "through foods, music, languages and traditions"]'::jsonb,3,'Immigrants enrich culture.','original'),
('113.19.c.10.C',4,'Which demographic concept describes how quickly a population grows?','["growth rate", "relative location", "latitude", "elevation"]'::jsonb,0,'Growth rate measures change.','original'),
('113.19.c.10.D',4,'Rapid population growth in Texas cities creates a need for more...','["volcanoes", "schools, roads and water supplies", "deserts", "glaciers"]'::jsonb,1,'Growth strains infrastructure.','original'),
('113.19.c.11.A',3,'The growth of oil and railroads helped lead to the urbanization of Texas by...','["ending industry", "stopping trade", "creating jobs in cities", "closing towns"]'::jsonb,2,'Cities grew with industry.','original'),
('113.19.c.11.B',3,'Urbanization changed Texas jobs from mostly farming to more...','["mining only", "hunting only", "fishing only", "manufacturing and service jobs"]'::jsonb,3,'Cities create diverse jobs.','original'),
('113.19.c.12.A',3,'A decline in world oil prices would most directly affect Texas by...','["reducing income for oil workers and the state budget", "ending tourism", "raising cotton prices", "stopping rain"]'::jsonb,0,'Texas is tied to global markets.','original'),
('113.19.c.12.B',3,'In a free enterprise system, prices in Texas stores depend on...','["tradition alone", "supply and demand", "a king''s decision", "the weather only"]'::jsonb,1,'Markets set prices.','original'),
('113.19.c.12.C',3,'The aerospace industry in Texas is closely tied to...','["the Chisholm Trail", "Spindletop", "NASA''s Johnson Space Center in Houston", "Spanish missions"]'::jsonb,2,'NASA brought high-tech jobs.','original'),
('113.19.c.13.A',3,'The Texas Constitution reflects limited government by...','["giving one person all power", "ending elections", "removing courts", "dividing power among branches and limiting officials"]'::jsonb,3,'Limited government protects rights.','original'),
('113.19.c.13.B',4,'Compared to the U.S. Constitution, the Texas Constitution is...','["longer and amended more often", "shorter and never amended", "identical", "unwritten"]'::jsonb,0,'Texas''s constitution is long and detailed.','original'),
('113.19.c.14.A',3,'Which level of government in Texas manages local issues like city streets and police?','["federal government only", "municipal (city) government", "the state Supreme Court", "the military"]'::jsonb,1,'Cities handle local services.','original'),
('113.19.c.14.A',3,'Texas counties are led by a...','["state senate", "school board", "commissioners court", "city council only"]'::jsonb,2,'County judge and commissioners govern the county.','original'),
('113.19.c.14.B',3,'Which is a major source of revenue for Texas local governments?','["lottery of land", "tariffs", "gold mines", "property taxes"]'::jsonb,3,'Local governments rely on property taxes.','original'),
('113.19.c.14.B',3,'Texas does not collect a state...','["personal income tax", "franchise tax", "property tax", "sales tax"]'::jsonb,0,'Texas has no personal income tax.','original'),
('113.19.c.15.A',3,'Which is a right of Texas citizens?','["ignoring laws", "voting in elections", "skipping jury duty", "avoiding taxes"]'::jsonb,1,'Voting is a basic right.','original'),
('113.19.c.15.B',3,'Which is a civic responsibility of Texas citizens?','["littering", "disobeying laws", "serving on a jury when called", "ignoring elections"]'::jsonb,2,'Jury duty is a civic duty.','original'),
('113.19.c.16.A',4,'Why do political parties and interest groups hold different views on Texas issues?','["they do not vote", "they share identical goals", "they avoid government", "they have different values and goals"]'::jsonb,3,'Different groups, different priorities.','original'),
('113.19.c.16.B',3,'Why is a free press important in a democratic society?','["it informs citizens and holds government accountable", "it replaces courts", "it hides news", "it removes elections"]'::jsonb,0,'Free press supports democracy.','original'),
('113.19.c.17.A',3,'A leadership quality of good elected officials is...','["ignoring laws", "honesty and responsibility", "avoiding voters", "secrecy"]'::jsonb,1,'Leaders must be trustworthy.','original'),
('113.19.c.17.B',3,'Barbara Jordan was a Texas leader known for...','["leading cattle drives", "discovering oil", "serving in the U.S. Congress and her powerful speeches", "founding the Alamo"]'::jsonb,2,'She was a civil rights leader.','original'),
('113.19.c.17.B',3,'John Nance Garner of Uvalde served as...','["Governor during the Revolution", "President of the Republic of Texas", "President of Mexico", "Vice President of the United States"]'::jsonb,3,'He was FDR''s vice president.','original'),
('113.19.c.18.A',3,'Which festival celebrates Texas''s Czech heritage?','["Czech Fest in West or Wharton", "Oktoberfest only", "Cinco de Mayo only", "Mardi Gras"]'::jsonb,0,'Czech communities hold festivals.','original'),
('113.19.c.18.B',3,'Many Texans maintain their heritage by celebrating...','["only government holidays", "traditional holidays, foods and languages", "no traditions", "only new holidays"]'::jsonb,1,'Heritage is kept through customs.','original'),
('113.19.c.18.C',3,'Many Texas place names such as San Antonio and El Paso show influence from...','["Chinese", "Dutch", "Spanish", "Russian"]'::jsonb,2,'Spanish names reflect colonial history.','original'),
('113.19.c.18.D',4,'J. Frank Dobie is known as a Texas...','["railroad engineer", "general", "oil baron", "author who wrote about Texas folklore and history"]'::jsonb,3,'Dobie wrote about Texas heritage.','original'),
('113.19.c.19.A',3,'Which comparison shows technological change over time?','["from the telegraph to cell phones", "from oxen to oxen", "from soil to soil", "from rain to rain"]'::jsonb,0,'Technology evolves.','original'),
('113.19.c.19.B',3,'Michael DeBakey of Houston is known for...','["discovering Spindletop", "pioneering heart surgery", "leading cattle drives", "inventing barbed wire"]'::jsonb,1,'He advanced cardiovascular medicine.','original'),
('113.19.c.19.C',4,'Air conditioning helped the growth of Texas cities by...','["ending storms", "creating oil", "making hot summers more comfortable for living and working", "removing the sun"]'::jsonb,2,'Cooling technology supported growth.','original'),
('113.19.c.19.D',4,'The cotton gin changed Texas agriculture by...','["producing oil", "replacing railroads", "ending cotton farming", "speeding the processing of cotton and increasing demand for it"]'::jsonb,3,'It boosted cotton production.','original'),
('113.19.c.19.E',4,'Advances in transportation and communication have made Texas more...','["interdependent with other regions and nations", "independent of trade", "isolated", "closed to travel"]'::jsonb,0,'Technology links economies.','original'),
('113.19.c.20.A',3,'A diary written by a Texas settler in 1850 is a...','["textbook", "primary source", "encyclopedia", "secondary source"]'::jsonb,1,'Firsthand account.','original'),
('113.19.c.20.A',3,'A Texas history textbook published last year is a...','["letter from the Alamo", "primary source", "secondary source", "diary"]'::jsonb,2,'Written long after the events.','original'),
('113.19.c.20.B',3,'Which timeline order is correct?','["World War II, Spindletop, Great Depression", "Spindletop, World War II, Great Depression", "Great Depression, Spindletop, World War II", "Spindletop (1901), Great Depression (1929), World War II (1941)"]'::jsonb,3,'Absolute chronology orders events by date.','original'),
('113.19.c.20.C',3,'Which visual is best for comparing Texas city populations?','["a bar graph", "a portrait", "a flag", "a lyric sheet"]'::jsonb,0,'Graphs compare data.','original'),
('113.19.c.20.D',4,'A letter written by a Mexican officer about the Alamo may differ from a Texan''s account because of different...','["page lengths", "points of view and bias", "fonts", "time zones"]'::jsonb,1,'Perspective shapes accounts.','original'),
('113.19.c.20.F',3,'To judge a source about Texas history, a student should check the...','["font color", "cover size", "author''s credentials and evidence", "page number"]'::jsonb,2,'Credible sources show evidence.','original'),
('113.19.c.21.A',3,'A thematic map of Texas could show...','["a poem", "only city names", "a recipe", "annual rainfall across the state"]'::jsonb,3,'Thematic maps display data themes.','original'),
('113.19.c.21.B',4,'A map showing most Texans living near Dallas, Houston and San Antonio helps analyze...','["population distribution", "ocean tides", "rainfall only", "elevation only"]'::jsonb,0,'Patterns show where people live.','original'),
('113.19.c.22.A',3,'The word ''annexation'' means...','["dividing a country", "adding territory to a larger country", "ending a war", "building a dam"]'::jsonb,1,'Texas was annexed by the U.S.','original'),
('113.19.c.22.B',3,'A bibliography in a report is used to...','["add a poem", "hide the author", "list sources that were used", "lengthen the title"]'::jsonb,2,'It credits sources.','original'),
('113.19.c.22.D',3,'Civil discourse in a debate about Texas history means...','["refusing to listen", "insulting others", "interrupting often", "listening and responding respectfully"]'::jsonb,3,'Respectful discussion.','original'),
('113.19.c.23.A',3,'A caucus in a political process is a...','["meeting where members discuss candidates or issues", "census", "trial", "vote of a king"]'::jsonb,0,'Caucuses are part of political processes.','original'),
('113.19.c.23.B',4,'A good decision-making process begins by...','["announcing the final choice", "identifying the problem and gathering information", "avoiding options", "ignoring evidence"]'::jsonb,1,'Define, research, consider options.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
